```typescript
'use client';

import { useRouter, useSearchParams } from 'next/navigation';
import styles from './TaskFilterToolbar.module.css';

export default function TaskFilterToolbar() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const currentSort = searchParams.get('sortBy') || 'due_date';

  const handleSortChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    const params = new URLSearchParams(searchParams);
    params.set('sortBy', e.target.value);
    router.push(`/?${params.toString()}`);
  };
```

- **`useSearchParams()`**: Reads current URL parameters (e.g. `?sortBy=topic`).
- **`router.push('/?sortBy=topic')`**: Updates the browser URL to `/?sortBy=topic`.
- **How it updates the UI**: Changing the URL triggers Next.js to re-evaluate `app/page.tsx` on the server with the new `sortBy` parameter, querying SQLite sorted by topic, and sending fresh HTML back to the screen!

