/* Light Canvas Page Layout */
.mainContainer {
  max-width: 56rem;
  margin: 0 auto;
  padding: 2.5rem 1rem;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  gap: 2rem;
  background-color: #f8fafc;
  color: #0f172a;
