/* Section Title */
.section {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.sectionTitle {
  font-size: 1.25rem;
  font-weight: 700;
  color: #1e40af;
}

/* Empty State Card */
.emptyState {
  text-align: center;
  padding: 3.5rem 1rem;
  border: 2px dashed #cbd5e1;
  border-radius: 0.75rem;
  background-color: #ffffff;
}

.emptyText {
  color: #64748b;
  font-weight: 500;
}

.taskGrid {
  display: grid;
  grid-template-columns: 1fr;
  gap: 1.25rem;
}

@media (min-width: 768px) {
  .taskGrid {
    grid-template-columns: repeat(2, 1fr);
  }
}

/* Dark Sleek Card Container */
.cardContainer {
