  gap: 0.75rem;
  margin-bottom: 0.75rem;
}

.title {
  font-weight: 700;
  font-size: 1.125rem;
  color: #60a5fa;
  margin: 0;
}

/* Badges */
.badge {
  font-size: 0.75rem;
  font-weight: 600;
  padding: 0.25rem 0.625rem;
  border-radius: 9999px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.statusComplete {
  background-color: #064e3b;
  color: #6ee7b7;
}

.statusInProgress {
  background-color: #451a03;
  color: #fcd34d;
}

.statusTodo {
  background-color: #172554;
  color: #93c5fd;
}

/* Description */
.description {
  font-size: 0.875rem;
  color: #cbd5e1;
  margin: 0 0 1rem 0;
  line-height: 1.5;
}

/* Footer & Meta */
.footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-top: 1px solid #334155;
  padding-top: 0.75rem;
  color: #94a3b8;
  font-size: 0.8125rem;
}

.metaGroup {
  display: flex;
  align-items: center;
  gap: 0.75rem;
}

.topicTag {
  background-color: #0f172a;
  color: #38bdf8;
  font-weight: 600;
  padding: 0.125rem 0.5rem;
  border-radius: 0.375rem;
  border: 1px solid #1e3a8a;
}

.overdueBadge {
  background-color: #7f1d1d;
  color: #fca5a5;
  padding: 0.2rem 0.6rem;
  border-radius: 9999px;
  font-size: 0.75rem;
  font-weight: 700;
  animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}

@keyframes pulse {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.4; }
