  background: none;
  border: none;
  font-size: 1.25rem;
  color: #94a3b8;
  cursor: pointer;
  transition: color 0.2s;
}

.btnClose:hover {
  color: #f8fafc;
}

/* Form Layout */
.form {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.gridTwo {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 1rem;
}

