### 📦 Step-by-Step Guide: Archived Tasks Section & Unarchive Dialog

Here is how to build the **Archived Tasks Modal** feature so users can view archived tasks and restore (unarchive) them back to the active board:

---

### Step 1: Add Database Functions in [src/lib/tasks.ts](file:///c:/Users/mahla/critical_projects/SDP_Lab_1_To-do-app/src/lib/tasks.ts)

Add `getArchivedTasks()` and `unarchiveTask(id)` at the bottom of [src/lib/tasks.ts](file:///c:/Users/mahla/critical_projects/SDP_Lab_1_To-do-app/src/lib/tasks.ts):

```typescript
export function getArchivedTasks(): Task[] {
    const sql = `SELECT * FROM tasks WHERE is_archived = 1 ORDER BY created_at DESC`;
    const tasks = db.prepare(sql).all() as Task[];

    return tasks.map(task => ({
        ...task,
        is_overdue: computeIsOverdue(task.due_date, task.status)
    }));
}

export function unarchiveTask(id: number) {
    return db.prepare(`UPDATE tasks SET is_archived = 0 WHERE id = ?`).run(id);
}
```

---

### Step 2: Add Server Action in [src/lib/actions.ts](file:///c:/Users/mahla/critical_projects/SDP_Lab_1_To-do-app/src/lib/actions.ts)

Update the imports at the top of [src/lib/actions.ts](file:///c:/Users/mahla/critical_projects/SDP_Lab_1_To-do-app/src/lib/actions.ts) to include `unarchiveTask` and export `unarchiveTaskAction`:

```typescript
import { createTask, updateTask, archiveTask, unarchiveTask } from './tasks';

// Export Unarchive Action
export async function unarchiveTaskAction(id: number) {
    unarchiveTask(id);
